namespace SupportTickets.Domain.Enums;

public enum TicketStatus
{
    Open = 0,
    InProgress = 1,
    Resolved = 2,
    Closed = 3,
    Cancelled = 4
}

namespace SupportTickets.Domain.Enums;

public enum TicketPriority
{
    Low = 0,
    Medium = 1,
    High = 2,
    Critical = 3
}

namespace SupportTickets.Domain.Entities;

public class User
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;

    public ICollection<Ticket> CreatedTickets { get; set; } = new List<Ticket>();
    public ICollection<Ticket> AssignedTickets { get; set; } = new List<Ticket>();
    public ICollection<TicketComment> Comments { get; set; } = new List<TicketComment>();
}

using SupportTickets.Domain.Enums;

namespace SupportTickets.Domain.Entities;

public class Ticket
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public TicketPriority Priority { get; set; }
    public TicketStatus Status { get; set; } = TicketStatus.Open;
    public int? AssignedToId { get; set; }
    public int CreatedById { get; set; }
    public DateTimeOffset CreatedAt { get; set; }

    public User? AssignedTo { get; set; }
    public User CreatedBy { get; set; } = null!;
    public ICollection<TicketComment> Comments { get; set; } = new List<TicketComment>();
}

namespace SupportTickets.Domain.Entities;

public class TicketComment
{
    public int Id { get; set; }
    public int TicketId { get; set; }
    public string Body { get; set; } = string.Empty;
    public int CreatedById { get; set; }
    public DateTimeOffset CreatedAt { get; set; }

    public Ticket Ticket { get; set; } = null!;
    public User CreatedBy { get; set; } = null!;
}

using SupportTickets.Domain.Enums;

namespace SupportTickets.Domain.Rules;

public static class TicketStatusTransitionRules
{
    private static readonly IReadOnlyDictionary<TicketStatus, IReadOnlySet<TicketStatus>> Allowed =
        new Dictionary<TicketStatus, IReadOnlySet<TicketStatus>>
        {
            [TicketStatus.Open] = new HashSet<TicketStatus> { TicketStatus.InProgress, TicketStatus.Cancelled },
            [TicketStatus.InProgress] = new HashSet<TicketStatus> { TicketStatus.Resolved, TicketStatus.Cancelled },
            [TicketStatus.Resolved] = new HashSet<TicketStatus> { TicketStatus.Closed },
            [TicketStatus.Closed] = new HashSet<TicketStatus>(),
            [TicketStatus.Cancelled] = new HashSet<TicketStatus>()
        };

    public static bool CanTransition(TicketStatus from, TicketStatus to) =>
        Allowed.TryGetValue(from, out var next) && next.Contains(to);

    public static IReadOnlySet<TicketStatus> GetAllowedTransitions(TicketStatus from) =>
        Allowed.TryGetValue(from, out var next) ? next : new HashSet<TicketStatus>();
}

using SupportTickets.Domain.Enums;

namespace SupportTickets.Domain.Exceptions;

public class InvalidStatusTransitionException : Exception
{
    public TicketStatus From { get; }
    public TicketStatus To { get; }

    public InvalidStatusTransitionException(TicketStatus from, TicketStatus to)
        : base($"Cannot transition from {from} to {to}.")
    {
        From = from;
        To = to;
    }
}

namespace SupportTickets.Domain.Exceptions;

public class NotFoundException : Exception
{
    public NotFoundException(string message) : base(message)
    {
    }
}

