namespace SupportTickets.Api.Validation;

[AttributeUsage(AttributeTargets.Property | AttributeTargets.Parameter)]
public sealed class AllowedTicketPriorityAttribute : ValidationAttribute
{
    private static readonly string AllowedList = string.Join(", ", Enum.GetNames<TicketPriority>());

    public AllowedTicketPriorityAttribute()
        : base($"Priority must be one of: {AllowedList}.")
    {
    }

    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        if (value is null)
        {
            return new ValidationResult("Priority is required.", new[] { validationContext.MemberName ?? "Priority" });
        }

        var raw = value as string ?? value.ToString();
        if (string.IsNullOrWhiteSpace(raw))
        {
            return new ValidationResult("Priority is required.", new[] { validationContext.MemberName ?? "Priority" });
        }

        if (!Enum.TryParse<TicketPriority>(raw.Trim(), ignoreCase: true, out var parsed)
            || !Enum.IsDefined(parsed)
            || int.TryParse(raw.Trim(), out _))
        {
            // Reject numeric-only values so clients must send named priorities.
            if (int.TryParse(raw.Trim(), out var asInt) && Enum.IsDefined(typeof(TicketPriority), asInt))
            {
                return new ValidationResult(
                    $"Priority must be one of: {AllowedList}.",
                    new[] { validationContext.MemberName ?? "Priority" });
            }

            if (!Enum.TryParse<TicketPriority>(raw.Trim(), ignoreCase: true, out parsed)
                || !Enum.GetNames<TicketPriority>().Any(n => n.Equals(raw.Trim(), StringComparison.OrdinalIgnoreCase)))
            {
                return new ValidationResult(
                    $"Priority must be one of: {AllowedList}.",
                    new[] { validationContext.MemberName ?? "Priority" });
            }
        }

        // Accept only defined named values (case-insensitive).
        if (!Enum.GetNames<TicketPriority>().Any(n => n.Equals(raw.Trim(), StringComparison.OrdinalIgnoreCase)))
        {
            return new ValidationResult(
                $"Priority must be one of: {AllowedList}.",
                new[] { validationContext.MemberName ?? "Priority" });
        }

        return ValidationResult.Success;
    }
}

using System.ComponentModel.DataAnnotations;
using SupportTickets.Domain.Enums;

namespace SupportTickets.Api.Validation;

[AttributeUsage(AttributeTargets.Property | AttributeTargets.Parameter)]
public sealed class AllowedTicketPriorityAttribute : ValidationAttribute
{
    private static readonly HashSet<string> AllowedNames =
        new(Enum.GetNames<TicketPriority>(), StringComparer.OrdinalIgnoreCase);

    private static readonly string AllowedList = string.Join(", ", Enum.GetNames<TicketPriority>());

    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        var member = validationContext.MemberName ?? "Priority";

        if (value is null || (value is string s && string.IsNullOrWhiteSpace(s)))
        {
            return new ValidationResult("Priority is required.", new[] { member });
        }

        var raw = (value as string ?? value.ToString())!.Trim();

        // Require named values (Low, Medium, High, Critical) — not bare integers.
        if (!AllowedNames.Contains(raw))
        {
            return new ValidationResult(
                $"Priority must be one of: {AllowedList}.",
                new[] { member });
        }

        return ValidationResult.Success;
    }
}

