using SupportTickets.Domain.Enums;

namespace SupportTickets.Domain.Rules;

/// <summary>
/// Explicit allow-list of ticket status transitions.
/// Anything not listed here is rejected by the transition service.
/// </summary>
public static class TransitionMap
{
    public static readonly IReadOnlyDictionary<TicketStatus, IReadOnlyList<TicketStatus>> Allowed =
        new Dictionary<TicketStatus, IReadOnlyList<TicketStatus>>
        {
            [TicketStatus.Open] = new[] { TicketStatus.InProgress, TicketStatus.Cancelled },
            [TicketStatus.InProgress] = new[] { TicketStatus.Resolved, TicketStatus.Cancelled },
            [TicketStatus.Resolved] = new[] { TicketStatus.Closed },
            [TicketStatus.Closed] = Array.Empty<TicketStatus>(),
            [TicketStatus.Cancelled] = Array.Empty<TicketStatus>()
        };

    public static bool CanTransition(TicketStatus from, TicketStatus to) =>
        GetAllowedNext(from).Contains(to);

    public static IReadOnlyList<TicketStatus> GetAllowedNext(TicketStatus from) =>
        Allowed.TryGetValue(from, out var next) ? next : Array.Empty<TicketStatus>();
}

using SupportTickets.Domain.Enums;
using SupportTickets.Domain.Rules;

namespace SupportTickets.Domain.Exceptions;

/// <summary>
/// Thrown when a ticket status change is not allowed by <see cref="TransitionMap"/>.
/// </summary>
public class InvalidTransitionException : Exception
{
    public TicketStatus FromStatus { get; }
    public TicketStatus ToStatus { get; }
    public IReadOnlyList<TicketStatus> AllowedNextStatuses { get; }

    public InvalidTransitionException(TicketStatus fromStatus, TicketStatus toStatus)
        : base(BuildMessage(fromStatus, toStatus, TransitionMap.GetAllowedNext(fromStatus)))
    {
        FromStatus = fromStatus;
        ToStatus = toStatus;
        AllowedNextStatuses = TransitionMap.GetAllowedNext(fromStatus);
    }

    private static string BuildMessage(
        TicketStatus from,
        TicketStatus to,
        IReadOnlyList<TicketStatus> allowedNext)
    {
        if (allowedNext.Count == 0)
        {
            return $"Cannot transition from {from} to {to}. {from} is a terminal status; no further transitions are allowed.";
        }

        var allowed = string.Join(", ", allowedNext);
        return $"Cannot transition from {from} to {to}. Allowed next statuses from {from}: {allowed}.";
    }
}

using System.ComponentModel.DataAnnotations;
using SupportTickets.Api.Validation;
using SupportTickets.Domain.Enums;

namespace SupportTickets.Api.DTOs.Tickets;

public class TransitionStatusRequest
{
    [Required(ErrorMessage = "Status is required.")]
    [AllowedTicketStatus]
    public string Status { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;
using SupportTickets.Domain.Enums;

namespace SupportTickets.Api.Validation;

[AttributeUsage(AttributeTargets.Property | AttributeTargets.Parameter)]
public sealed class AllowedTicketStatusAttribute : ValidationAttribute
{
    private static readonly HashSet<string> AllowedNames =
        new(Enum.GetNames<TicketStatus>(), StringComparer.OrdinalIgnoreCase);

    private static readonly string AllowedList = string.Join(", ", Enum.GetNames<TicketStatus>());

    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        var member = validationContext.MemberName ?? "Status";

        if (value is null || (value is string s && string.IsNullOrWhiteSpace(s)))
        {
            return new ValidationResult("Status is required.", new[] { member });
        }

        var raw = (value as string ?? value.ToString())!.Trim();
        if (!AllowedNames.Contains(raw))
        {
            return new ValidationResult(
                $"Status must be one of: {AllowedList}.",
                new[] { member });
        }

        return ValidationResult.Success;
    }
}

using Microsoft.EntityFrameworkCore;
using SupportTickets.Api.DTOs.Tickets;
using SupportTickets.Domain.Enums;
using SupportTickets.Domain.Exceptions;
using SupportTickets.Domain.Rules;
using SupportTickets.Infrastructure.Data;

namespace SupportTickets.Api.Services;

public class TicketStatusTransitionService
{
    private readonly AppDbContext _db;

    public TicketStatusTransitionService(AppDbContext db)
    {
        _db = db;
    }

    /// <summary>
    /// Applies a status change only if <see cref="TransitionMap"/> allows
    /// current → target. Otherwise throws <see cref="InvalidTransitionException"/>.
    /// </summary>
    public async Task<TicketResponse> TransitionAsync(
        int ticketId,
        TransitionStatusRequest request,
        CancellationToken cancellationToken = default)
    {
        var ticket = await _db.Tickets
            .FirstOrDefaultAsync(t => t.Id == ticketId, cancellationToken)
            ?? throw new NotFoundException($"Ticket with id {ticketId} was not found.");

        var target = Enum.Parse<TicketStatus>(request.Status.Trim(), ignoreCase: true);
        var current = ticket.Status;

        if (current == target)
        {
            // Idempotent no-op: already in the requested status.
            return await LoadResponseAsync(ticketId, cancellationToken);
        }

        if (!TransitionMap.CanTransition(current, target))
        {
            throw new InvalidTransitionException(current, target);
        }

        ticket.Status = target;
        await _db.SaveChangesAsync(cancellationToken);

        return await LoadResponseAsync(ticketId, cancellationToken);
    }

    private async Task<TicketResponse> LoadResponseAsync(int id, CancellationToken cancellationToken)
    {
        var ticket = await _db.Tickets
            .AsNoTracking()
            .Include(t => t.CreatedBy)
            .Include(t => t.AssignedTo)
            .FirstAsync(t => t.Id == id, cancellationToken);

        return new TicketResponse
        {
            Id = ticket.Id,
            Title = ticket.Title,
            Description = ticket.Description,
            Priority = ticket.Priority,
            Status = ticket.Status,
            AssignedToId = ticket.AssignedToId,
            AssignedToName = ticket.AssignedTo?.Name,
            CreatedById = ticket.CreatedById,
            CreatedByName = ticket.CreatedBy.Name,
            CreatedAt = ticket.CreatedAt
        };
    }
}

